import sys
from collections import deque

def transform(grid):
    R, C = len(grid), len(grid[0])
    bg = grid[0][0]
    # collect non-bg colors; the shape color is the most common non-bg (or use all non-bg as walls)
    out = [row[:] for row in grid]
    visited = [[False]*C for _ in range(R)]
    q = deque()
    for r in range(R):
        for c in (0, C-1):
            if grid[r][c] == bg and not visited[r][c]:
                visited[r][c] = True; q.append((r, c))
    for c in range(C):
        for r in (0, R-1):
            if grid[r][c] == bg and not visited[r][c]:
                visited[r][c] = True; q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc] and grid[nr][nc] == bg:
                visited[nr][nc] = True
                q.append((nr, nc))
    for r in range(R):
        for c in range(C):
            if grid[r][c] == bg and not visited[r][c]:
                out[r][c] = 4
    return out
