    seen = [[False]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == bg and not visited[r][c] and not seen[r][c]:
                comp = []
                qq = deque([(r, c)])
                seen[r][c] = True
                while qq:
                    rr, cc = qq.popleft()
                    comp.append((rr, cc))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
